using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Logging;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides web search capabilities for the research agent.
/// Uses DuckDuckGo Lite as a free, no-API-key search engine.
/// </summary>
public sealed partial class WebSearchTool(HttpClient httpClient, ILogger<WebSearchTool> logger)
{
    [Description("Searches the web for information on a given query. Returns a list of search result titles, URLs, and snippets.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query string")] string query,
        [Description("Maximum number of results to return (default 5)")] int maxResults = 5)
    {
        logger.LogInformation("Searching the web for: {Query}", query);

        try
        {
            var encodedQuery = Uri.EscapeDataString(query);
            var url = $"https://lite.duckduckgo.com/lite/?q={encodedQuery}";

            using var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.Add("User-Agent", "ResearchAgent/1.0");

            var response = await httpClient.SendAsync(request);
            response.EnsureSuccessStatusCode();

            var html = await response.Content.ReadAsStringAsync();
            var results = ParseSearchResults(html, maxResults);

            if (results.Count == 0)
            {
                return $"No results found for '{query}'.";
            }

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for '{query}':");
            sb.AppendLine();
            for (var i = 0; i < results.Count; i++)
            {
                var (title, resultUrl, snippet) = results[i];
                sb.AppendLine($"{i + 1}. **{title}**");
                sb.AppendLine($"   URL: {resultUrl}");
                if (!string.IsNullOrWhiteSpace(snippet))
                {
                    sb.AppendLine($"   {snippet}");
                }
                sb.AppendLine();
            }

            logger.LogInformation("Found {Count} results for: {Query}", results.Count, query);
            return sb.ToString();
        }
        catch (HttpRequestException ex)
        {
            logger.LogWarning(ex, "Web search failed for query: {Query}", query);
            return $"Search failed: {ex.Message}. Try a different query or try again later.";
        }
    }

    [Description("Fetches the text content of a web page at the given URL. Use this to read full articles found via search.")]
    public async Task<string> FetchWebPageAsync(
        [Description("The URL of the web page to fetch")] string url,
        [Description("Maximum number of characters to return (default 3000)")] int maxLength = 3000)
    {
        logger.LogInformation("Fetching web page: {Url}", url);

        try
        {
            using var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.Add("User-Agent", "ResearchAgent/1.0");

            var response = await httpClient.SendAsync(request);
            response.EnsureSuccessStatusCode();

            var html = await response.Content.ReadAsStringAsync();
            var text = StripHtml(html);

            if (text.Length > maxLength)
            {
                text = text[..maxLength] + "\n\n[Content truncated...]";
            }

            return string.IsNullOrWhiteSpace(text)
                ? "Could not extract meaningful text from this page."
                : text;
        }
        catch (HttpRequestException ex)
        {
            logger.LogWarning(ex, "Failed to fetch page: {Url}", url);
            return $"Failed to fetch page: {ex.Message}";
        }
    }

    private static List<(string Title, string Url, string Snippet)> ParseSearchResults(string html, int maxResults)
    {
        var results = new List<(string, string, string)>();

        // Parse DuckDuckGo Lite result links and snippets
        var linkMatches = ResultLinkRegex().Matches(html);
        var snippetMatches = SnippetRegex().Matches(html);

        for (var i = 0; i < Math.Min(linkMatches.Count, maxResults); i++)
        {
            var linkMatch = linkMatches[i];
            var rawUrl = WebUtility.HtmlDecode(linkMatch.Groups[1].Value);
            var title = WebUtility.HtmlDecode(StripHtml(linkMatch.Groups[2].Value)).Trim();

            var snippet = i < snippetMatches.Count
                ? WebUtility.HtmlDecode(StripHtml(snippetMatches[i].Groups[1].Value)).Trim()
                : string.Empty;

            if (!string.IsNullOrWhiteSpace(title) && rawUrl.StartsWith("http"))
            {
                results.Add((title, rawUrl, snippet));
            }
        }

        return results;
    }

    private static string StripHtml(string html)
    {
        var text = HtmlTagRegex().Replace(html, " ");
        text = WhitespaceRegex().Replace(text, " ");
        return WebUtility.HtmlDecode(text).Trim();
    }

    [GeneratedRegex("""<a[^>]+href="([^"]*)"[^>]*class="result-link"[^>]*>(.*?)</a>""", RegexOptions.Singleline | RegexOptions.IgnoreCase)]
    private static partial Regex ResultLinkRegex();

    [GeneratedRegex("""<td[^>]*class="result-snippet"[^>]*>(.*?)</td>""", RegexOptions.Singleline | RegexOptions.IgnoreCase)]
    private static partial Regex SnippetRegex();

    [GeneratedRegex("<[^>]+>")]
    private static partial Regex HtmlTagRegex();

    [GeneratedRegex(@"\s+")]
    private static partial Regex WhitespaceRegex();
}

using System.ComponentModel;
using System.Text;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Logging;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides note-taking capabilities for the research agent to organize findings.
/// </summary>
public sealed class NoteTool(ILogger<NoteTool> logger)
{
    private readonly List<Note> _notes = [];

    [Description("Saves a research note with a title and content. Use this to record key findings during research.")]
    public string SaveNote(
        [Description("A short title for the note")] string title,
        [Description("The content/body of the note")] string content,
        [Description("The source URL where this information was found (optional)")] string? sourceUrl = null)
    {
        var note = new Note
        {
            Id = _notes.Count + 1,
            Title = title,
            Content = content,
            SourceUrl = sourceUrl,
            CreatedAt = DateTime.UtcNow,
        };

        _notes.Add(note);
        logger.LogInformation("Note saved: #{Id} - {Title}", note.Id, note.Title);
        return $"Note #{note.Id} saved: '{title}'";
    }

    [Description("Lists all saved research notes with their titles and IDs.")]
    public string ListNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        var sb = new StringBuilder();
        sb.AppendLine($"Saved notes ({_notes.Count} total):");
        foreach (var note in _notes)
        {
            sb.AppendLine($"  #{note.Id}: {note.Title}");
        }

        return sb.ToString();
    }

    [Description("Retrieves the full content of a saved note by its ID.")]
    public string GetNote([Description("The ID of the note to retrieve")] int noteId)
    {
        var note = _notes.Find(n => n.Id == noteId);
        if (note is null)
        {
            return $"Note #{noteId} not found.";
        }

        var sb = new StringBuilder();
        sb.AppendLine($"Note #{note.Id}: {note.Title}");
        sb.AppendLine($"Saved at: {note.CreatedAt:u}");
        if (!string.IsNullOrWhiteSpace(note.SourceUrl))
        {
            sb.AppendLine($"Source: {note.SourceUrl}");
        }

        sb.AppendLine();
        sb.AppendLine(note.Content);
        return sb.ToString();
    }

    [Description("Generates a formatted summary of all research notes collected so far.")]
    public string GetResearchSummary()
    {
        if (_notes.Count == 0)
        {
            return "No research notes to summarize.";
        }

        var sb = new StringBuilder();
        sb.AppendLine("=== Research Summary ===");
        sb.AppendLine();

        foreach (var note in _notes)
        {
            sb.AppendLine($"## {note.Title}");
            sb.AppendLine(note.Content);
            if (!string.IsNullOrWhiteSpace(note.SourceUrl))
            {
                sb.AppendLine($"Source: {note.SourceUrl}");
            }

            sb.AppendLine();
        }

        sb.AppendLine($"Total notes: {_notes.Count}");
        return sb.ToString();
    }

    private sealed class Note
    {
        public int Id { get; init; }
        public required string Title { get; init; }
        public required string Content { get; init; }
        public string? SourceUrl { get; init; }
        public DateTime CreatedAt { get; init; }
    }
}

