 services.AddHttpClient<WebSearchTool>(client =>
 {
     client.Timeout = TimeSpan.FromSeconds(15);
 });

 services.AddSingleton<NoteTool>();

 var openAiChatClient = new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient();
 services.AddSingleton<IChatClient>(openAiChatClient);

 var provider = services.BuildServiceProvider();

 var chatClient = provider.GetRequiredService<IChatClient>();
 var loggerFactory = provider.GetRequiredService<ILoggerFactory>();
 var webSearchTool = provider.GetRequiredService<WebSearchTool>();
 var noteTool = provider.GetRequiredService<NoteTool>();

 // --- Register tools from the tool classes ---
 var tools = new List<AITool>
 {
     AIFunctionFactory.Create(webSearchTool.SearchWebAsync),
     AIFunctionFactory.Create(webSearchTool.FetchWebPageAsync),
     AIFunctionFactory.Create(noteTool.SaveNote),
     AIFunctionFactory.Create(noteTool.ListNotes),
     AIFunctionFactory.Create(noteTool.GetNote),
     AIFunctionFactory.Create(noteTool.GetResearchSummary),
 };

 // --- Create the agent ---
 var instructions = """
     You are a thorough research agent. Your job is to research a topic by:
     1. Searching the web for relevant information using the search tool.
     2. Fetching and reading promising web pages for detailed information.
     3. Taking organized notes on key findings using the note-taking tool.
     4. After gathering enough information (at least 3 good sources), compile your
        notes and provide a comprehensive summary.

     Always cite your sources. Be thorough but focused. Prioritize authoritative sources.
     When you have gathered sufficient information, use GetResearchSummary to review your
     notes, then provide a final synthesized summary to the user.
     """;

 var agent = new ChatClientAgent(
     chatClient,
     instructions: instructions,
     name: "ResearchAgent",
     description: "An agent that researches topics by searching the web and taking notes",
     tools: tools,
     loggerFactory: loggerFactory,
     services: provider);

 // --- Get the research topic ---
 Console.ForegroundColor = ConsoleColor.Cyan;
 Console.WriteLine("╔══════════════════════════════════════════╗");
 Console.WriteLine("║       🔍 AI Research Agent               ║");
 Console.WriteLine("╚══════════════════════════════════════════╝");
 Console.ResetColor();
 Console.WriteLine();

 string topic;
 if (args.Length > 0)
 {
     topic = string.Join(' ', args);
 }
 else
 {
     Console.Write("Enter a research topic: ");
     topic = Console.ReadLine()?.Trim() ?? string.Empty;
 }

 if (string.IsNullOrWhiteSpace(topic))
 {
     Console.Error.WriteLine("No topic provided. Exiting.");
     return 1;
 }

 Console.WriteLine();
 Console.ForegroundColor = ConsoleColor.Yellow;
 Console.WriteLine($"Researching: {topic}");
 Console.ResetColor();
 Console.WriteLine(new string('─', 50));

 // --- Run the agent ---
 var runOptions = new ChatClientAgentRunOptions
 {
     ChatOptions = new ChatOptions
     {
         Temperature = 0f,
         MaxOutputTokens = 4096,
     },
 };

 var prompt = $"Please research the following topic and provide a comprehensive summary with sources: {topic}";

 try
 {
     await foreach (var update in agent.RunStreamingAsync(prompt, options: runOptions))
     {
         if (!string.IsNullOrEmpty(update.Text))
         {
             Console.Write(update.Text);
         }
     }

     Console.WriteLine();
 }
 catch (Exception ex)
 {
     Console.ForegroundColor = ConsoleColor.Red;
     Console.Error.WriteLine($"\nError: {ex.Message}");
     Console.ResetColor();
     return 1;
 }

 Console.WriteLine();
 Console.ForegroundColor = ConsoleColor.Green;
 Console.WriteLine("Research complete!");
 Console.ResetColor();

 return 0;
